  for(let y=0;y<=17;y++){ctx.beginPath();ctx.moveTo(...xy([0,y]));ctx.lineTo(...xy([10,y]));ctx.stroke();}
  for(const b of data.scene.walls)rect(b,'#b8c5bd');
