 let attempted=false;
 async function initialize(retry=false){if(data||loading||(attempted&&!retry))return;attempted=true;loading=true;try{await loadScript('assets/teaser-flow-data.js',()=>!!window.CLEAR_TEASER_FLOW);data=window.CLEAR_TEASER_FLOW;range.max=data.timeline.durationSeconds;const sequence=root.querySelector('.flow-sequence');data.conditionedOrder.forEach((i,j)=>{if(j)sequence.append(document.createTextNode(' → '));const node=document.createElement('span');node.dataset.flowObject=i;node.textContent='Object '+i;sequence.append(node);});draw();observeAutomaticScene(viewer);}catch{caption.textContent='The flow data could not load. ';const retry=document.createElement('button');retry.type='button';retry.textContent='Retry';retry.onclick=()=>{retry.remove();initialize(true);};caption.append(retry);}finally{loading=false;}}
 play.onclick=()=>command({playing:!playing});root.querySelector('#flow-replay').onclick=()=>command({time:0,playing:true});range.oninput=()=>seek(+range.value);
 root.querySelector('#maze-flow-sample').onchange=e=>{sample=+e.target.value;time=0;playing=false;const active=!!viewer.querySelector('iframe');viewer.dispatchEvent(new Event('reset-viewer'));viewer.dataset.scene='teaser-flow-'+sample;pending=null;draw();if(active)command({time:0,playing:true});};
