/* assets/continuous-layout.js */
/* User-started evidence shares the recorded playback clocks. */
(() => {
 document.querySelectorAll('.viewer[data-autostart]').forEach(observeAutomaticScene);
 document.querySelectorAll('.media-tile[data-scene^="mpc-"]').forEach(tile=>attachEgoVideo(tile,tile.dataset.scene));
 document.querySelectorAll('.execution-body-viewer').forEach(viewer=>{
  const main=viewer.querySelector('.preview-video'),ego=viewer.querySelector('.ego-inset video');
  wireEgoVideo(viewer,main,ego);
 });
 const replayRows=[...document.querySelectorAll('[data-replay-body] .execution-process-grid')];
 for(const row of replayRows)row.addEventListener('scroll',()=>{
  for(const other of replayRows)if(Math.abs(other.scrollLeft-row.scrollLeft)>1)other.scrollLeft=row.scrollLeft;
 },{passive:true});
 document.querySelector('[data-paper-figure]')?.addEventListener('click',()=>{
  const dialog=document.querySelector('#resource-dialog');dialog.querySelector('h2').textContent='Architecture in the paper';
  const image=document.createElement('img');image.src=clearAssetURL('assets/pipeline-anonymous.png');image.alt='Original CLEAR paper architecture';image.style.cssText='width:100%;height:100%;object-fit:contain';
  dialog.querySelector('[data-resource-content]').replaceChildren(image);const download=dialog.querySelector('[data-resource-download]');download.href=image.src;download.textContent='Download figure';dialog.showModal();
 });
 const failure=document.querySelector('[data-failure-example="execution"] video');
 failure?.addEventListener('timeupdate',()=>{
  failure.closest('article').querySelector('output').textContent=failure.currentTime<1.545?'Approaching the object':failure.currentTime<14.14?'Pushing · Contact lost at 14.14 s':failure.currentTime<15?'Contact lost · Goal not reached':'Box stopped · Goal still 1.33 m away';
 });
})();

// One replay clock drives the measured body and palm views, including seeks.
(() => {
 const views=[...document.querySelectorAll('[data-execution-clock]')],clocks={};
 function synchronize(){for(const view of views){
  const clock=clocks[view.dataset.clockGroup||'g1'];if(!clock)continue;
  const video=view.querySelector('.preview-video'),ego=view.querySelector('.ego-inset video');
  if (!clock.playing && clock.time === 0 && video.readyState === 0) continue;
  const limit=Number.isFinite(video.duration)?Math.max(0,video.duration-.04):Infinity;
  const target=Math.min(clock.time,limit),finished=clock.time>=limit;
  for(const media of [video]){
   if(media.preload!=='auto')media.preload='auto';
   media.playbackRate=clock.speed;
   if(media.readyState&&!media.seeking&&Math.abs(media.currentTime-Math.min(target,media.duration-.04))>.14)media.currentTime=Math.max(0,Math.min(target,media.duration-.04));
   if(clock.playing&&!finished&&!view.querySelector('iframe.scene-ready')){if(media.paused)media.play().catch(()=>{});}else media.pause();
  }
  syncEgoClock(view,{time:target,playing:clock.playing&&!finished,rate:clock.speed},'external');
  const native=view.querySelector('iframe.scene-ready');
  if(native&&(view._clockFrame!==native||view._clockSent===undefined||Math.abs(target-view._clockSent)>.08)){native.contentWindow.postMessage({type:'clear-playback-command',time:target,playing:false},'*');view._clockSent=target;view._clockFrame=native;}
 }}
 document.addEventListener('clear-mpc-clock',event=>{clocks[event.detail.group||'g1']=event.detail;synchronize();});
 for(const view of views){view.querySelector('.preview-video').addEventListener('loadedmetadata',synchronize);view.addEventListener('scene-settled',synchronize);}
})();

;

/* assets/failure-map.js */
/* Saved flow states and the archived planning rejection sequence. */
(() => {
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 for(const canvas of document.querySelectorAll('[data-failure-map],[data-planning-failure]')){
  const flow=canvas.hasAttribute('data-failure-map'),article=canvas.closest('article');
  const slider=article.querySelector('input'),play=article.querySelector('[data-failure-play]'),replay=article.querySelector('[data-failure-replay]'),output=article.querySelector('.failure-controls output'),status=article.querySelector('.failure-stage');
  let data=null,loading=false,visible=false,time=0,playing=!reduced,last=0,raf=0,bounds;
  function draw(){
   if(!data)return;
   const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;
   const ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);
   const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.fillStyle='#f7f8f3';ctx.fillRect(0,0,w,h);
   const scene=flow?data.scene:data,g=window.CLEAR_FAILURE_GEOMETRY;
   const candidate=flow?null:data.candidates[Math.min(data.candidates.length-1,Math.floor(time*data.candidates.length))];
   const paths=flow?g.sample(data.referenceFlow[0],time):candidate.paths;
   const [low,high]=bounds,scale=Math.min((w-32)/(high[0]-low[0]),(h-42)/(high[1]-low[1]));
   const xy=p=>[w/2+(p[0]-(high[0]+low[0])/2)*scale,h/2+10-(p[1]-(high[1]+low[1])/2)*scale];
   const rect=(b,color)=>{const p=xy([b[0],b[3]]);ctx.fillStyle=color;ctx.fillRect(p[0],p[1],(b[2]-b[0])*scale,(b[3]-b[1])*scale);};
   for(const t of scene.terrain||[])rect(t.bounds,t.kind==='ramp'?'#deeee3':t.kind==='stair_tread'?'#f1e1d5':'#edf2e9');
   for(const b of scene.walls)rect(b,'#c0c9bd');
   const polygon=(points,fill,stroke,width=1.5)=>{ctx.beginPath();points.map(xy).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();};
   const violations=[];
   paths.forEach((path,index)=>{
    const obj=scene.objects[path.object],color=['#568f9a','#ad805a','#7c83a6'][index%3];
    path.poses.slice(1).forEach((b,j)=>{
     const a=path.poses[j],bad=g.blocked(a,b,obj.size,scene.walls);
     if(bad)violations.push({object:path.object,segment:j});
     ctx.beginPath();ctx.moveTo(...xy(a));ctx.lineTo(...xy(b));ctx.strokeStyle=bad?'#b94732':color;ctx.lineWidth=bad?3:2;ctx.stroke();
     ctx.beginPath();ctx.arc(...xy(b),3.5,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke();
    });
    for(const j of [Math.floor(path.poses.length/2),path.poses.length-1]){
     const pose=path.poses[j],bad=scene.walls.some(b=>g.overlap(pose,obj.size,b));
     polygon(g.footprint(pose,obj.size),bad?'#b9473240':color+'30',bad?'#b94732':color,2);
    }
   });
   scene.objects.forEach((o,i)=>{polygon(g.footprint(o.pose,o.size),'#d7b49a','#8c7059');const q=xy(o.pose);ctx.font='12px Arial';ctx.fillStyle='#374333';ctx.textAlign='center';ctx.fillText(String(i),q[0],q[1]+4);});
   for(const [p,label]of [[scene.start,'Start'],[scene.goal,'Goal']]){const q=xy(p);ctx.fillStyle='#486a48';ctx.beginPath();ctx.arc(...q,4.5,0,Math.PI*2);ctx.fill();ctx.font='13px Arial';ctx.textAlign='center';ctx.fillText(label,q[0],q[1]-10);}
   canvas.dataset.flowTime=time.toFixed(3);canvas.dataset.overlapSegments=JSON.stringify(violations);
   canvas.dataset.source=flow?'recorded-teaser-flow-draw-0':'archived-planning-decisions';
   slider.value=time;output.textContent=flow?'t = '+time.toFixed(2):(candidate.id+1)+' / '+data.candidates.length;
   status.textContent=flow?(time===0?'Gaussian initialization':time<1?'Generating box waypoints. Red segments intersect obstacles.':'t = 1 · Generated paths intersect obstacles. Clearance failed.'):(time===1?'All 8 candidates rejected. No valid plan returned.':`Candidate ${candidate.id+1}: ${candidate.invalidDecode?'invalid generated path':candidate.rejection==='INTERACTION_REJECTED'?'interaction rejected':'no route to the goal'}`);
   play.textContent=playing?'Pause':'Play';
  }
  function tick(now){raf=0;if(!visible||!playing||!data||document.hidden){last=0;return;}if(last)time=Math.min(1,time+(now-last)/(flow?8000:16000));last=now;if(time===1)playing=false;draw();if(playing)raf=requestAnimationFrame(tick);}
  function schedule(){if(visible&&playing&&data&&!raf&&!document.hidden)raf=requestAnimationFrame(tick);}
  let attempted=false;
  async function load(retry=false){
   if(data||loading||(attempted&&!retry))return;attempted=true;loading=true;
   try{
    await loadScript('assets/failure-geometry.js',()=>!!window.CLEAR_FAILURE_GEOMETRY);
    await loadScript(flow?'assets/teaser-flow-data.js':'assets/failure-planning-data.js',()=>flow?!!window.CLEAR_TEASER_FLOW:!!window.CLEAR_FAILURE_PLANNING);
    data=flow?window.CLEAR_TEASER_FLOW:window.CLEAR_FAILURE_PLANNING;
    const points=flow?data.referenceFlow[0].states.flatMap(s=>s.flatMap(p=>p.poses)):data.walls.flatMap(b=>[[b[0],b[1]],[b[2],b[3]]]);
    const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);
    bounds=[[Math.min(-1,...xs)-.5,Math.min(-1,...ys)-.5],[Math.max(flow?11:12,...xs)+.5,Math.max(flow?18:12,...ys)+.5]];
    draw();schedule();
   }catch(error){status.textContent='Could not load recorded states. Select Replay to retry.';data=null;}finally{loading=false;}
  }
  play.onclick=()=>{playing=!playing;if(playing&&time===1)time=0;last=0;draw();schedule();};
  replay.onclick=()=>{time=0;playing=true;last=0;if(!data)load(true);else{draw();schedule();}};
  slider.oninput=()=>{time=Number(slider.value);playing=false;last=0;draw();};
  document.addEventListener('visibilitychange',()=>{last=0;if(document.hidden){cancelAnimationFrame(raf);raf=0;}else schedule();});
  new ResizeObserver(draw).observe(canvas);
  new IntersectionObserver(entries=>{visible=entries.at(-1).isIntersecting;last=0;if(!visible){cancelAnimationFrame(raf);raf=0;return;}load();schedule();},{threshold:.1}).observe(canvas);
 }
})();

;

/* assets/spot-eef.js */
/* Measured single-gripper trajectories. No generated candidate forecasts. */
(() => {
 const root=document.querySelector('#spot-process');if(!root)return;
 const panels=[...root.querySelectorAll('[data-spot-process]')],play=root.querySelector('[data-spot-play]'),slider=root.querySelector('input'),counter=root.querySelector('[data-spot-time]'),status=root.querySelector('.spot-loading');
 let data=null,loading=false,visible=false,playing=false,elapsed=0,end=0,last=0,frame=0,mode='3d',bounds=null;
 const camera={yaw:Math.PI/6,pitch:.6,zoom:1,pan:[0,0]},W=560,colors={eef:'#b85c5b',object:'#1a7369',reference:'#3964a3'};
 function at(rows,t){let lo=0,hi=rows.length-1;while(lo<hi){const m=Math.ceil((lo+hi)/2);if(rows[m][0]<=t)lo=m;else hi=m-1;}const a=rows[lo],b=rows[Math.min(lo+1,rows.length-1)],u=b[0]>a[0]?Math.max(0,Math.min(1,(t-a[0])/(b[0]-a[0]))):0;return a.map((v,i)=>i?v+(b[i]-v)*u:t);}
 function local(p,r){return [p[0]-r.reference[0][0],p[1]-r.reference[0][1],p[2]];}
 function rotate(p){return [Math.cos(camera.yaw)*p[0]+Math.sin(camera.yaw)*p[1],Math.sin(camera.pitch)*(Math.sin(camera.yaw)*p[0]-Math.cos(camera.yaw)*p[1])-Math.cos(camera.pitch)*p[2]];}
 function project(p){const q=rotate(p.map((v,a)=>v-(bounds[a][0]+bounds[a][1])/2)),span=Math.hypot(...bounds.map(b=>b[1]-b[0])),scale=330/span*camera.zoom;return [280+q[0]*scale+camera.pan[0],212+q[1]*scale+camera.pan[1]];}
 const tx=t=>58+t/end*470,ty=(v,a)=>157+a*155-(v-bounds[a][0])/(bounds[a][1]-bounds[a][0])*100;
 function stroke(ctx,points,color,width=2,dash=[]){if(!points.length)return;ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.setLineDash([]);}
 function dot(ctx,p,color,r=5){ctx.beginPath();ctx.arc(...p,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();}
 function path(ctx,rows,r,offset,color,width){const points=rows.map(row=>local(row.slice(offset,offset+3),r));if(mode==='3d')stroke(ctx,points.map(project),color,width);else for(let a=0;a<3;a++)stroke(ctx,points.map((p,i)=>[tx(rows[i][0]),ty(p[a],a)]),color,width);}
 function render(){
  if(!data)return;
  root.dataset.elapsed=elapsed.toFixed(4);root.dataset.view=mode;slider.value=elapsed/end;play.textContent=playing?'Pause':'Play';counter.textContent=`${elapsed.toFixed(1)} / ${end.toFixed(1)} s`;
  for(const panel of panels){
   const r=data[panel.dataset.spotProcess],time=Math.min(elapsed,r.duration),now=at(r.observed,time),rows=r.observed.filter(row=>row[0]<time).concat([now]),c=panel.querySelector('canvas');c.width=W;c.height=mode==='3d'?420:560;
   const ctx=c.getContext('2d');ctx.fillStyle='#fbfcfa';ctx.fillRect(0,0,W,c.height);ctx.font=Math.max(14,11*W/(c.clientWidth||W))+'px Arial';ctx.fillStyle='#647269';
   if(mode==='3d'){
    const [x,y,z]=bounds;
    for(let i=Math.ceil(x[0]);i<=x[1];i++)stroke(ctx,[project([i,y[0],0]),project([i,y[1],0])],'#e1e6df',1);
    for(let i=Math.ceil(y[0]);i<=y[1];i++)stroke(ctx,[project([x[0],i,0]),project([x[1],i,0])],'#e1e6df',1);
    const origin=[x[0],y[0],0];[[x[1],y[0],0],[x[0],y[1],0],[x[0],y[0],z[1]]].forEach((p,a)=>{stroke(ctx,[project(origin),project(p)],'#85917f',1.5);const q=project(p);ctx.fillText(['X','Y','Z'][a],q[0]+5,q[1]-5);});
    stroke(ctx,r.reference.map(p=>project(local(p,r))),colors.reference,3,[7,5]);
    for(const p of [r.reference[0],r.reference.at(-1)])dot(ctx,project(local(p,r)),colors.reference,5);
    ctx.fillText('Drag to rotate · scroll to zoom',16,405);
   }else{
    for(let a=0;a<3;a++){ctx.fillText(['X (m)','Y (m)','Z (m)'][a],12,29+a*155);for(const value of [bounds[a][0],(bounds[a][0]+bounds[a][1])/2,bounds[a][1]]){const y=ty(value,a);stroke(ctx,[[58,y],[528,y]],'#e1e6df',1);ctx.fillText(value.toFixed(1),12,y+4);}for(const t of [0,end/2,end]){stroke(ctx,[[tx(t),57+a*155],[tx(t),157+a*155]],'#e1e6df',1);if(a===2)ctx.fillText(t.toFixed(1),tx(t)-12,491);}}
    ctx.fillText('Recorded time (s) · fixed scales',16,535);
   }
   path(ctx,r.observed,r,1,'#d4d7d2',1.3);path(ctx,rows,r,4,colors.object,3);path(ctx,rows,r,1,colors.eef,3);
   for(const [offset,color] of [[1,colors.eef],[4,colors.object]]){const p=local(now.slice(offset,offset+3),r);if(mode==='3d')dot(ctx,project(p),color,6);else for(let a=0;a<3;a++)dot(ctx,[tx(time),ty(p[a],a)],color,5);}
   panel.querySelector('.mpc-recording-status').textContent=r.toppleTime!==null&&time>=r.toppleTime?'Toppled':elapsed>=r.duration?'Recording ended':'';
   c.dataset.time=String(time);c.dataset.eef=JSON.stringify(now.slice(1,4));c.dataset.object=JSON.stringify(now.slice(4,7));c.dataset.coordinateBounds=JSON.stringify(bounds);c.dataset.source=r.scene;c.dataset.hands='1';
  }
  root.dispatchEvent(new CustomEvent('clear-mpc-clock',{bubbles:true,detail:{group:'spot',time:elapsed,playing:playing&&visible&&!document.hidden,speed:2}}));
 }
 function tick(now){frame=0;if(!data||!visible||!playing||document.hidden)return;if(last)elapsed=Math.min(end,elapsed+2*(now-last)/1000);last=now;if(elapsed>=end)playing=false;render();schedule();}
 function schedule(){if(data&&visible&&playing&&!document.hidden&&!frame){frame=requestAnimationFrame(tick);}}
 let attempted=false;
 async function initialize(retry=false){if(data||loading||(attempted&&!retry))return;attempted=true;loading=true;status.textContent='Loading recorded EEF motion…';try{
  await loadScript('assets/spot-eef-data.js',()=>!!window.CLEAR_SPOT_EEF);data=window.CLEAR_SPOT_EEF;end=Math.max(...Object.values(data).map(r=>r.duration));
  const ext=[[0,0],[0,0],[0,0]];for(const r of Object.values(data)){const include=p=>local(p,r).forEach((v,a)=>{ext[a][0]=Math.min(ext[a][0],v);ext[a][1]=Math.max(ext[a][1],v);});r.reference.forEach(include);r.observed.forEach(row=>{include(row.slice(1,4));include(row.slice(4,7));});}
  bounds=ext.map(([lo,hi])=>[Math.floor(lo*5)/5-.15,Math.ceil(hi*5)/5+.15]);status.hidden=true;render();schedule();
 }catch(error){data=null;status.textContent='Could not load recorded paths. ';const retry=document.createElement('button');retry.textContent='Retry';retry.onclick=()=>initialize(true);status.append(retry);}finally{loading=false;}}
 function stopFrame(){cancelAnimationFrame(frame);frame=0;last=0;}
 new IntersectionObserver(entries=>{visible=entries.at(-1).isIntersecting;if(visible){initialize();last=0;render();schedule();}else{stopFrame();render();}},{rootMargin:'0px'}).observe(root);
 play.onclick=()=>{if(!data){playing=true;initialize();return;}playing=!playing;if(playing&&elapsed>=end)elapsed=0;last=0;render();schedule();};
 root.querySelector('[data-spot-replay]').onclick=()=>{elapsed=0;playing=true;last=0;render();schedule();};slider.oninput=()=>{elapsed=+slider.value*end;last=0;render();};
 root.querySelectorAll('[data-spot-view]').forEach(button=>button.onclick=()=>{mode=button.dataset.spotView;root.querySelectorAll('[data-spot-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));render();});
 function reset(){Object.assign(camera,{yaw:Math.PI/6,pitch:.6,zoom:1,pan:[0,0]});render();}
 for(const panel of panels){const c=panel.querySelector('canvas');let pointer=null;
  c.onpointerdown=e=>{if(mode!=='3d')return;pointer=[e.pointerId,e.clientX,e.clientY];c.setPointerCapture(e.pointerId);};
  c.onpointermove=e=>{if(!pointer||e.pointerId!==pointer[0])return;const dx=(e.clientX-pointer[1])*W/c.clientWidth,dy=(e.clientY-pointer[2])*W/c.clientWidth;pointer=[e.pointerId,e.clientX,e.clientY];if(e.shiftKey){camera.pan[0]+=dx;camera.pan[1]+=dy;}else{camera.yaw-=dx*.008;camera.pitch=Math.max(.12,Math.min(1.4,camera.pitch+dy*.006));}render();};
  for(const type of ['pointerup','pointercancel','lostpointercapture'])c.addEventListener(type,()=>{pointer=null;});
  c.addEventListener('wheel',e=>{if(mode!=='3d')return;e.preventDefault();camera.zoom=Math.max(.6,Math.min(4,camera.zoom*Math.exp(-e.deltaY*.001)));render();},{passive:false});c.ondblclick=reset;
  c.onkeydown=e=>{const actions={Home:reset,ArrowLeft:()=>camera.yaw+=.12,ArrowRight:()=>camera.yaw-=.12,ArrowUp:()=>camera.pitch=Math.min(1.4,camera.pitch+.08),ArrowDown:()=>camera.pitch=Math.max(.12,camera.pitch-.08),'+':()=>camera.zoom=Math.min(4,camera.zoom*1.15),'-':()=>camera.zoom=Math.max(.6,camera.zoom/1.15)};if(mode==='3d'&&actions[e.key]){e.preventDefault();actions[e.key]();render();}};
 }
 document.addEventListener('visibilitychange',()=>{stopFrame();render();schedule();});reduced.addEventListener('change',()=>{if(reduced.matches){playing=false;stopFrame();render();}});
})();

;

/* assets/training-losses.js */
/* One original CLEAR run. Shading is local step variation, never seed uncertainty. */
(() => {
  const root = document.querySelector('#training-losses');
  if (!root) return;
  const charts = [...root.querySelectorAll('[data-loss]')], series = new Map();
  let data, pendingLoad, pinnedTerm = null, index = null, hovered = null, scheduled = false;
  const value = n => Number(n.toPrecision(6)).toString();
  function nearest(target) {
    let lo = 0, hi = data.samples.length - 1;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (data.samples[mid].step < target) lo = mid + 1; else hi = mid; }
    return lo && Math.abs(data.samples[lo - 1].step - target) < Math.abs(data.samples[lo].step - target) ? lo - 1 : lo;
  }
  function renderChart(chart) {
    const key = chart.dataset.loss, canvas = chart.querySelector('canvas'), rows = series.get(key);
    const w = canvas.clientWidth, h = key === 'loss' ? 260 : 200, dpr = Math.min(devicePixelRatio || 1, 2);
    if (!w) return;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr); canvas.style.height = h + 'px';
    const ctx = canvas.getContext('2d'); ctx.scale(dpr, dpr);
    const left = 50, right = w - 12, top = 14, bottom = h - 40;
    const maximum = Math.max(...rows.map(row => Math.max(row.raw, row.mean + row.std)));
    const unit = 10 ** Math.floor(Math.log10(maximum || 1));
    const ymax = Math.ceil(maximum / unit * 2) / 2 * unit || 1;
    const x = n => left + n / data.maxStep * (right - left), y = n => bottom - n / ymax * (bottom - top);
    chart._plot = {left, right};
    ctx.font = '13px Arial'; ctx.fillStyle = '#73796e'; ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const v = ymax * i / 4;
      ctx.strokeStyle = '#e8ece4'; ctx.beginPath(); ctx.moveTo(left, y(v)); ctx.lineTo(right, y(v)); ctx.stroke();
      ctx.textAlign = 'right'; ctx.fillText(Number(v.toPrecision(3)).toString(), left - 6, y(v) + 4);
    }
    const ticks = w < 300 ? 2 : 4;
    for (let i = 0; i <= ticks; i++) {
      const t = data.maxStep * i / ticks;
      ctx.textAlign = i === ticks ? 'right' : i === 0 ? 'left' : 'center'; ctx.fillText(t ? (t / 1000) + 'k' : '0', x(t), h - 15);
    }
    ctx.textAlign = 'right'; ctx.fillText('Step', right, h - 4);
    ctx.save(); ctx.beginPath(); ctx.rect(left, top, right - left, bottom - top + 1); ctx.clip();
    ctx.beginPath();
    rows.forEach((row, i) => ctx[i ? 'lineTo' : 'moveTo'](x(row.step), y(row.mean + row.std)));
    for (let i = rows.length - 1; i >= 0; i--) ctx.lineTo(x(rows[i].step), y(Math.max(0, rows[i].mean - rows[i].std)));
    ctx.closePath(); ctx.fillStyle = 'rgba(70,123,154,.18)'; ctx.fill();
    ctx.beginPath(); rows.forEach((row, i) => ctx[i ? 'lineTo' : 'moveTo'](x(row.step), y(row.mean)));
    ctx.strokeStyle = '#467b9a'; ctx.lineWidth = 1.6; ctx.stroke(); ctx.restore();
    const row = index === null ? null : rows[index];
    chart.dataset.inspected = JSON.stringify(row); chart.dataset.inspectedStep = row?.step ?? '';
    if (row) {
      ctx.strokeStyle = '#939f89'; ctx.setLineDash([3, 4]); ctx.beginPath(); ctx.moveTo(x(row.step), top); ctx.lineTo(x(row.step), bottom); ctx.stroke(); ctx.setLineDash([]);
      ctx.fillStyle = '#467b9a'; ctx.beginPath(); ctx.arc(x(row.step), y(row.mean), 3.5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x(row.step), y(row.raw), 4, 0, Math.PI * 2); ctx.fillStyle = '#fff'; ctx.fill(); ctx.strokeStyle = '#467b9a'; ctx.lineWidth = 1.5; ctx.stroke();
    }
    const tooltip = chart.querySelector('.loss-tooltip'); tooltip.hidden = hovered !== chart || !row;
    if (!tooltip.hidden) {
      tooltip.replaceChildren(); const heading = document.createElement('strong'); heading.textContent = 'Step ' + row.step.toLocaleString('en-US'); tooltip.append(heading);
      for (const [label, n] of [['Raw loss', row.raw], ['Local mean', row.mean], ['Std. deviation', row.std]]) {
        const entry = document.createElement('div'); entry.className = 'loss-tooltip-row';
        const name = document.createElement('span'), metric = document.createElement('span'); name.textContent = label; metric.textContent = value(n); entry.append(name, metric); tooltip.append(entry);
      }
      tooltip.style.left = Math.max(0, Math.min(w - tooltip.offsetWidth, x(row.step) + 12)) + 'px';
      tooltip.style.top = (canvas.offsetTop + 14) + 'px';
    }
  }
  function render() { if (data) charts.forEach(renderChart); }
  function schedule() { if (scheduled) return; scheduled = true; requestAnimationFrame(() => { scheduled = false; render(); }); }
  function inspect(chart, target) { index = nearest(target); hovered = chart; schedule(); }
  function initialize() {
    if (data) return Promise.resolve();
    if (!pendingLoad) pendingLoad = loadData();
    return pendingLoad;
  }
  async function loadData() {
    try {
      await loadScript('assets/training-loss-data.js', () => !!window.CLEAR_TRAINING_LOSSES);
      data = window.CLEAR_TRAINING_LOSSES;
      const radius = Math.floor(data.window / 2);
      for (const chart of charts) {
        const key = chart.dataset.loss;
        series.set(key, data.samples.map((row, i) => {
          const local = data.samples.slice(Math.max(0, i - radius), i + radius + 1).map(s => s[key]);
          const mean = local.reduce((sum, n) => sum + n, 0) / local.length;
          return {step:row.step, raw:row[key], mean, std:Math.sqrt(local.reduce((sum, n) => sum + (n - mean) ** 2, 0) / local.length)};
        }));
        const canvas = chart.querySelector('canvas');
        const pointerInspect = e => { const box = canvas.getBoundingClientRect(), plot = chart._plot; if (plot) inspect(chart, (e.clientX - box.left - plot.left) / (plot.right - plot.left) * data.maxStep); };
        canvas.addEventListener('pointermove', pointerInspect); canvas.addEventListener('pointerdown', pointerInspect);
        canvas.addEventListener('pointerleave', () => { if (document.activeElement === canvas) return; index = null; hovered = null; schedule(); });
        canvas.addEventListener('focus', () => { pinnedTerm = key; highlight(key); inspect(chart, data.samples[index ?? 0].step); });
        canvas.addEventListener('blur', () => { hovered = null; index = null; schedule(); });
        canvas.addEventListener('keydown', e => {
          if (!['ArrowLeft','ArrowRight','Home','End','Escape'].includes(e.key)) return; e.preventDefault();
          if (e.key === 'Escape') { canvas.blur(); return; }
          index = e.key === 'Home' ? 0 : e.key === 'End' ? data.samples.length - 1 : Math.max(0, Math.min(data.samples.length - 1, (index ?? 0) + (e.key === 'ArrowRight' ? 1 : -1)));
          hovered = chart; render(); const row = series.get(key)[index];
          root.querySelector('.loss-keyboard-status').textContent = chart.querySelector('h5').textContent + ', step ' + row.step.toLocaleString('en-US') + '. Raw loss ' + value(row.raw) + ', local mean ' + value(row.mean) + ', standard deviation ' + value(row.std) + '.';
        });
      }
      root.querySelector('.loss-loading').hidden = true; root.querySelector('.loss-content').hidden = false;
      new ResizeObserver(schedule).observe(root); render();
    } catch {
      data = null; const node = root.querySelector('.loss-loading'); node.textContent = 'Training curves could not load. ';
      const retry = document.createElement('button'); retry.type = 'button'; retry.textContent = 'Retry'; retry.onclick = () => { pendingLoad = null; retry.remove(); initialize(); }; node.append(retry);
    }
  }
  function highlight(key) { key ??= pinnedTerm; const keys=Array.isArray(key)?key:[key]; charts.forEach(chart => chart.classList.toggle('loss-term-active', keys.includes(chart.dataset.loss))); root.querySelectorAll('[data-loss-term]').forEach(button => button.classList.toggle('loss-term-active', keys.includes(button.dataset.lossTerm))); }
  const termKeys=term=>term.classList.contains('term-order')?['selection','order','kl']:term.classList.contains('term-flow')?['flow']:term.classList.contains('term-affordance')?['affordance']:['loss'];
  function inspectTerm(term){
    const keys=termKeys(term);highlight(keys);
    const chart=charts.find(c=>c.dataset.loss===keys[0]),strip=root.querySelector('.loss-chart-grid');
    if(chart&&strip.contains(chart))strip.scrollTo({left:chart.getBoundingClientRect().left-strip.getBoundingClientRect().left+strip.scrollLeft,behavior:reduced.matches?'instant':'smooth'});
  }
  root.addEventListener('pointerover',e=>{const term=e.target.closest('.objective-term');if(term&&!term.contains(e.relatedTarget))inspectTerm(term);});
  root.addEventListener('pointerout',e=>{const term=e.target.closest('.objective-term');if(term&&!term.contains(e.relatedTarget))highlight(null);});
  root.addEventListener('focusin',e=>{const term=e.target.closest('.objective-term');if(term)inspectTerm(term);});
  root.addEventListener('focusout',e=>{if(e.target.closest('.objective-term'))highlight(null);});
  root.addEventListener('click',e=>{const term=e.target.closest('.objective-term');if(term)inspectTerm(term);});
  root.addEventListener('keydown',e=>{const term=e.target.closest('.objective-term');if(term&&['Enter',' '].includes(e.key)){e.preventDefault();inspectTerm(term);}});
  root.querySelectorAll('[data-loss-term]').forEach(button => {
    button.addEventListener('pointerenter', () => highlight(button.dataset.lossTerm)); button.addEventListener('pointerleave', () => highlight(null));
    button.addEventListener('focus', () => highlight(button.dataset.lossTerm)); button.addEventListener('blur', () => highlight(null));
    button.onclick = async () => { pinnedTerm = button.dataset.lossTerm; await initialize(); if (!data) return; const chart = charts.find(c => c.dataset.loss === button.dataset.lossTerm); chart.scrollIntoView({behavior:reduced.matches ? 'instant' : 'smooth', block:'center'}); chart.querySelector('canvas').focus({preventScroll:true}); highlight(button.dataset.lossTerm); };
  });
  new IntersectionObserver(entries => { if (entries.some(e => e.isIntersecting)) initialize(); }, {rootMargin:'250px'}).observe(root);
})();

;
